'use client';

import type { ReactNode } from 'react';
import { css, cx } from 'styled-system/css';

export interface HeroPanelProps {
	eyebrow?: ReactNode;
	title: ReactNode;
	description?: ReactNode;
	actions?: ReactNode;
	media?: ReactNode;
	footer?: ReactNode;
	className?: string;
	copyClassName?: string;
	titleClassName?: string;
	descriptionClassName?: string;
	mediaClassName?: string;
}

const styles = {
	root: css({
		display: 'grid',
		gridTemplateColumns: { base: '1fr', xl: 'minmax(0, 1.05fr) minmax(20rem, 0.95fr)' },
		gap: '0',
		borderRadius: 'l3',
		bg: 'app.surface',
		boxShadow: '{shadows.whisper}',
		overflow: 'hidden',
	}),
	copy: css({
		display: 'flex',
		flexDirection: 'column',
		gap: '4',
		minWidth: 0,
		padding: { base: '5', md: '6', xl: '7' },
	}),
	eyebrow: css({
		display: 'inline-flex',
		alignItems: 'center',
		width: 'fit-content',
		paddingX: '3',
		paddingY: '1.5',
		borderRadius: 'full',
		bg: 'app.accent.soft',
		color: 'app.accent',
		textStyle: 'eyebrow',
	}),
	title: css({
		textStyle: 'h1',
		color: 'app.text',
		maxWidth: '20ch',
	}),
	description: css({
		textStyle: 'body',
		color: 'app.text.muted',
		maxWidth: '28rem',
		lineHeight: '1.65',
	}),
	actions: css({
		display: 'flex',
		alignItems: 'center',
		flexWrap: 'wrap',
		gap: '3',
	}),
	footer: css({
		paddingTop: '4',
		paddingX: '4',
		paddingY: '4',
		borderRadius: 'xl',
		bg: 'app.surface.muted',
		color: 'app.text.muted',
	}),
	media: css({
		minHeight: '100%',
		display: 'flex',
		alignItems: 'stretch',
		justifyContent: 'stretch',
		padding: { base: '4.5', md: '5' },
		background:
			'linear-gradient(180deg, var(--colors-app-surface-muted) 0%, var(--colors-app-canvas-subtle) 100%)',
	}),
};

export function HeroPanel({
	eyebrow,
	title,
	description,
	actions,
	media,
	footer,
	className,
	copyClassName,
	titleClassName,
	descriptionClassName,
	mediaClassName,
}: HeroPanelProps) {
	return (
		<section className={cx(styles.root, className)}>
			<div className={cx(styles.copy, copyClassName)}>
				{eyebrow && <div className={styles.eyebrow}>{eyebrow}</div>}
				<div className={cx(styles.title, titleClassName)}>{title}</div>
				{description && (
					<div className={cx(styles.description, descriptionClassName)}>{description}</div>
				)}
				{actions && <div className={styles.actions}>{actions}</div>}
				{footer && <div className={styles.footer}>{footer}</div>}
			</div>
			{media && <div className={cx(styles.media, mediaClassName)}>{media}</div>}
		</section>
	);
}
